SELECT tm.match_status, COUNT(*) 
FROM transplant_matching tm
GROUP BY tm.match_status;

SELECT DISTINCT match_status FROM transplant_matching WHERE match_rec_registry IN (
    SELECT adm_rev_registry FROM administrative_and_review 
    WHERE LOWER(exp_rev_stat_val) = 'approved'
);
